// วิธีแก้ใน JavaScript:
// 1. ให้เปลี่ยนคำขอ Fetch ให้ส่งด้วย method: 'POST'
// 2. ให้ append('_method', 'PUT') เข้าไปใน FormData

const formData = new FormData(editForm);
formData.append('_method', 'PUT'); // สำคัญมาก!

fetch(`http://localhost:8000/api/books/${id}`, {
  method: 'POST', // ต้องเป็น POST ห้ามเป็น PUT
  body: formData
});

// วิธีแก้: ย้ายและตรวจสอบให้แน่ใจว่า Route ของเราอยู่ใน routes/api.php
// ทุก Route ภายใต้ routes/api.php จะมี Prefix เป็น /api/... เสมอ
// และ Laravel จะปิดการตรวจ CSRF Token ให้โดยอัตโนมัติ!

// ตัวอย่าง URL ที่ถูกต้อง:
// http://localhost:8000/api/books
// http://localhost:8000/api/categories
